/* @autogenerated */
import { Component, input } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { TranslocoPipe } from '@jsverse/transloco';
import type { ActionContainerComponent } from './action-container.component';

/** Acciones de una fila: las que caben como botón y el resto en el menú "más". */
@Component({
  selector: 'action-row-menu',
  standalone: true,
  imports: [MatButtonModule, MatIconModule, MatMenuModule, MatTooltipModule, TranslocoPipe],
  styles: ':host { display: contents; }',
  template: `
    @let c = container();
    @let item = row();
    @for (action of c.inlineActions(item); track $index) {
      @if (action.contextual && !action.multiple && action.visible([item])()) {
        @if (action.icon()) {
          <button
            mat-icon-button
            aria-label="{{ action.label() }}"
            [matTooltip]="action.tooltip()"
            (click)="c.executeAction(action.name, [item])"
            [disabled]="!action.enabled(c.selectionModel.selected())()"
          >
            <mat-icon>{{ action.icon() }}</mat-icon>
          </button>
        } @else {
          <button
            mat-raised-button
            aria-label="{{ action.label() }}"
            [matTooltip]="action.tooltip()"
            (click)="c.executeAction(action.name, [item])"
            [disabled]="!action.enabled(c.selectionModel.selected())()"
          >
            {{ action.label() }}
          </button>
        }
      }
    }
    @if (c.inlineMenu(item).length > 0) {
      @let more = 'common.moreActions' | transloco;
      <button
        mat-icon-button
        aria-label="{{ more }}"
        [matTooltip]="more"
        [matMenuTriggerFor]="menu"
        (click)="c.showMenu(item); $event.stopPropagation()"
      >
        <mat-icon>more_vert</mat-icon>
      </button>
      <mat-menu #menu="matMenu">
        @for (action of c.inlineMenu(item); track $index) {
          @if (action.contextual && !action.multiple && action.visible([item])()) {
            <button
              mat-menu-item
              aria-label="{{ action.label() }}"
              (click)="c.executeAction(action.name, [item])"
              [disabled]="!action.enabled([item])()"
            >
              @if (action.icon()) {
                <mat-icon>{{ action.icon() }}</mat-icon>
              }
              {{ action.label() }}
            </button>
          }
        }
      </mat-menu>
    }
  `,
})
export class ActionRowMenuComponent {
  readonly container = input.required<ActionContainerComponent>();
  readonly row = input.required<any>();
}
